var e=[{glyph:`⌁`,text:`Why was I wrong on the ice-core dual text?`,tone:`blue`},{glyph:`◑`,text:`Explain infinitely many solutions simply`,tone:`violet`},{glyph:`◔`,text:`How do I stop running out of time in Module 2?`,tone:`amber`},{glyph:`★`,text:`Build me a 20-question set from my weak topics`,tone:`green`}],t=`Short version: you picked the choice that contradicted Ndlovu instead of the one that limited Oyola-Merced. On cross-text questions, find the concession first — the clause that grants the other author's premise — then look for what the second author restricts. Want me to build five more of these?`,n=`I looked at your last 40 questions. Vocabulary in context is costing you the most points — 27% accuracy over 46 attempts. Want a 10-question set on it?`,r=[`Why is B wrong here?`,`Explain this like I'm new`,`Give me a similar question`,`What should I drill tonight?`];function i(e){let t=e.toLowerCase();return t.includes(`drill`)||t.includes(`tonight`)?`Tonight: 10 questions on vocabulary in context, then 5 on transitions. Keep it under 15 minutes — your accuracy drops after that on evening sessions.`:t.includes(`wrong`)?`B looks right because it repeats a word from the passage. That is the trap: the question asks for function, not content. The correct choice describes what the sentence does — it gives a reason.`:`Short version: predict an answer in your own words before reading the choices, then eliminate anything that changes the meaning. Want a 5-question set to try it?`}export{e as a,n as i,i as n,t as r,r as t};